#!/usr/bin/env node
// PreToolUse(Edit|Write): protects files that must not be edited by hand.
// - migrations already on the main branch are immutable (write a new migration)
// - lockfiles are generated by the package manager
import path from 'node:path';
import { readInput, projectDir, relPath, run, denyPreToolUse } from './_lib.mjs';

const input = await readInput();
const root = projectDir(input);
const rel = relPath(input);
if (!rel) process.exit(0);

const LOCKFILES = /(^|\/)(package-lock\.json|pnpm-lock\.yaml|yarn\.lock|bun\.lockb?|Chart\.lock)$/;
if (LOCKFILES.test(rel)) {
  denyPreToolUse(`${path.basename(rel)} is generated. Change the manifest and run the package manager (npm install / helm dependency update) instead of editing the lockfile.`);
}

const MIGRATION = /(^|\/)(migrations?|drizzle|prisma\/migrations)\/.+\.(sql|ts|js|mjs|cjs)$/i;
if (MIGRATION.test(rel) && !/\.(test|spec)\./.test(rel)) {
  const bases = ['origin/HEAD', 'origin/main', 'origin/master', 'main', 'master'];
  for (const base of bases) {
    if (!run('git', ['rev-parse', '--verify', '--quiet', base], { cwd: root }).ok) continue;
    if (run('git', ['cat-file', '-e', `${base}:${rel}`], { cwd: root }).ok) {
      denyPreToolUse(`${rel} already exists on ${base}: applied migrations are immutable. Create a new migration that makes the change (expand/contract), do not edit history.`);
    }
    break;
  }
}
